package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import java.nio.file.*;import java.util.concurrent.atomic.AtomicInteger;
/** Wiring/negative-capability contracts; real clock and same-frame pipeline live in the separate integration fixture. */
public class TimedNativeBackContractTest {
 private String s(String name)throws Exception{return Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once",name)).replace("\r\n","\n");}
 @Test public void unissuedPermitCannotReadOrDispatchAndAttemptRemainsSpent(){AtomicInteger calls=new AtomicInteger();var p=new NativeBingReturnController.Ports(){public long elapsedRealtime(){return 1000;}public boolean authorityCurrent(BingNavigationSnapshot.Shape s){calls.incrementAndGet();return true;}public BingNavigationSnapshot.Ready originalSource(){calls.incrementAndGet();return null;}public BingNavigationSnapshot.Result observe(BingNavigationSnapshot.Shape s){calls.incrementAndGet();return null;}public void consumeReturn(ReviewShizukuBackActor.BackTarget t){calls.incrementAndGet();}public void pollPause(){calls.incrementAndGet();}};var actor=new ReviewShizukuBackActor(()->{calls.incrementAndGet();throw new AssertionError("No permit");});var c=NativeBingReturnController.timedAfterTap("new-task",p,actor);assertTrue(c.returnAfterTap(null).summary().contains("returnReason=AUTHORITY_LOST"));assertTrue(c.returnAfterTap(null).summary().contains("returnReason=ALREADY_ATTEMPTED"));assertEquals(0,calls.get());assertTrue(actor.knownClean());}
 @Test public void schedulingAndDispatchBothCheckMonotonicNotBefore()throws Exception{String c=s("NativeBingReturnController.java");assertTrue(c.contains("long action=permit.successfulTapElapsed()"));assertTrue(c.contains("long due=action+5000"));assertTrue(c.contains("while(ports.elapsedRealtime()<due)"));assertTrue(c.contains("if(exact!=target||ports.elapsedRealtime()<due||!current(permit))return false"));assertTrue(c.contains("backFinalGateElapsed=now;backGateSinceTap=now-tapDispatchElapsed;backGateSinceSuccess=now-action"));assertTrue(c.contains("action<tapDispatchElapsed"));assertTrue(c.contains("waitStart<action"));assertTrue(c.contains("successfulTapElapsed="));assertFalse(c.contains("System.currentTimeMillis"));}
 @Test public void noOldBrowserObservationBeforeTimedBack()throws Exception{String c=s("NativeBingReturnController.java");int start=c.indexOf("private Result timedReturn("),back=c.indexOf("var back=actor.back",start);String before=c.substring(start,back);assertFalse(before.contains("observe(permit)"));assertFalse(before.contains("sameBrowser"));assertTrue(before.contains("taskGuard(permit,original)"));assertTrue(c.contains("if(timed)return timedReturn(permit,original)"));}
 @Test public void delayAndExitAreNotCompletionEvidence()throws Exception{String c=s("NativeBingReturnController.java");int start=c.indexOf("private Result timedReturn("),post=c.indexOf("if(!back.commandExitZero()",start);String after=c.substring(post);for(String token:new String[]{"actor.knownClean()","ports.metadataClean()","observeTimedReturn(original)","ready.fresh(ports.elapsedRealtime())","ready.sameTask(original)","original.sameSource(ready)","Reason.RETURN_NOT_READY"})assertTrue(token,after.contains(token));assertFalse(after.contains("OBSERVED_TASK_COMPLETE"));}
 @Test public void waitAndReadBudgetAreBoundedAndGuarded()throws Exception{String c=s("NativeBingReturnController.java");assertTrue(c.contains("taskGuardObservations>=2"));assertTrue(c.contains("pauses++>=200"));assertFalse(c.contains("ports.elapsedRealtime()-action>=2500"));assertTrue(c.contains("guard.matches(original,ports.elapsedRealtime())&&ports.metadataClean()&&current(permit)"));assertTrue(c.contains("minimumDelayMs=5000"));assertTrue(c.contains("elapsedSinceSuccessfulTapAtBackGate="));}
 @Test public void legacyConstructionRemainsExplicitlyUntimed()throws Exception{String c=s("NativeBingReturnController.java");assertTrue(c.contains("this(runId,ports,actor,selectedPending,false)"));assertTrue(c.contains("new NativeBingReturnController(runId,ports,actor,true,true)"));assertTrue(c.contains("diagnostic(),false"));assertTrue(c.contains("browserObserved=observedBrowser"));}
 @Test public void timedPostUsesFullReturnProofHookOnly()throws Exception{String c=s("NativeBingReturnController.java");int start=c.indexOf("private Result timedReturn("),post=c.indexOf("if(!back.commandExitZero()",start);String after=c.substring(post);assertTrue(after.contains("observeTimedReturn(original)"));assertFalse(after.contains("observe(permit)"));assertTrue(after.contains("original.sameSource(ready)"));assertTrue(c.contains("default BingNavigationSnapshot.Result observeTimedReturn(BingNavigationSnapshot.Ready original){return BingNavigationSnapshot.Result.unknown();}"));}
 @Test public void noForegroundReadDuringSuccessDelay()throws Exception{String c=s("NativeBingReturnController.java");int start=c.indexOf("private Result timedReturn("),loop=c.indexOf("while(ports.elapsedRealtime()<due)",start),end=c.indexOf("if(!current(permit)||ports.elapsedRealtime()<due)",loop);String delay=c.substring(start,end);assertFalse(delay.contains("taskGuard(permit,original)"));assertFalse(delay.contains("observe(permit)"));assertFalse(delay.contains("observeTimedReturn"));assertTrue(delay.contains("if(!current(permit))return hold(permit,Reason.AUTHORITY_LOST,null)"));assertTrue(delay.contains("pauses++>=200"));String after=c.substring(end,c.indexOf("backActorReturnedElapsed=",end));assertEquals(2,after.split("taskGuard\\(permit,original\\)",-1).length-1);assertTrue(after.contains("ports.elapsedRealtime()<due"));}
}
